import Foundation

public struct SecretsFile: Codable, Sendable, Equatable {
    public let openai_api_key: String

    public init(openai_api_key: String = "") {
        self.openai_api_key = openai_api_key
    }
}

public struct SecretsStore: SecretStore, Sendable {
    public let fileURL: URL

    public init(
        fileURL: URL = Self.defaultFileURL()
    ) {
        self.fileURL = fileURL
    }

    public static func defaultFileURL(
        currentDirectoryPath: String = FileManager.default.currentDirectoryPath,
        fileManager: FileManager = .default
    ) -> URL {
        let cwd = URL(fileURLWithPath: currentDirectoryPath, isDirectory: true)
        let direct = cwd.appendingPathComponent("Config/secrets.json")
        if fileManager.fileExists(atPath: direct.deletingLastPathComponent().path) {
            return direct
        }

        let nested = cwd.appendingPathComponent("apps/dictator-main/Config/secrets.json")
        if fileManager.fileExists(atPath: nested.deletingLastPathComponent().path) {
            return nested
        }

        return direct
    }

    public static func defaultExampleFileURL(
        currentDirectoryPath: String = FileManager.default.currentDirectoryPath,
        fileManager: FileManager = .default
    ) -> URL {
        let cwd = URL(fileURLWithPath: currentDirectoryPath, isDirectory: true)
        let direct = cwd.appendingPathComponent("Config/secrets.example.json")
        if fileManager.fileExists(atPath: direct.deletingLastPathComponent().path) {
            return direct
        }

        let nested = cwd.appendingPathComponent("apps/dictator-main/Config/secrets.example.json")
        if fileManager.fileExists(atPath: nested.deletingLastPathComponent().path) {
            return nested
        }

        return direct
    }

    public func load() throws -> SecretsFile? {
        guard FileManager.default.fileExists(atPath: fileURL.path) else {
            return nil
        }
        do {
            let data = try Data(contentsOf: fileURL)
            return try JSONDecoder().decode(SecretsFile.self, from: data)
        } catch {
            throw DictatorError.configUpdateFailed("invalid secrets file: \(error)")
        }
    }

    public func getOpenAIKey() throws -> String? {
        guard let loaded = try load() else {
            return nil
        }
        let trimmed = loaded.openai_api_key.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }

    public func setOpenAIKey(_ key: String) throws {
        _ = key
        throw DictatorError.configUpdateFailed("secrets file is read-only")
    }

    public func clearOpenAIKey() throws {
        throw DictatorError.configUpdateFailed("secrets file is read-only")
    }
}

import Foundation

public enum APIKeyResolver {
    public static func resolve(
        fallback: () throws -> String?
    ) rethrows -> String? {
        guard let key = try fallback() else {
            return nil
        }
        return normalized(key)
    }

    public static func resolve(
        primary: () throws -> String?,
        fallback: () throws -> String?
    ) rethrows -> String? {
        if let first = try primary(), let normalizedFirst = normalized(first) {
            return normalizedFirst
        }
        guard let second = try fallback() else {
            return nil
        }
        return normalized(second)
    }

    private static func normalized(_ value: String) -> String? {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? nil : trimmed
    }
}

import DictatorCore
import Foundation

@main
struct DictatorServiceMain
{
    static func main() async
    {
        TraceLogger.reset()
        TraceLogger.log("DictatorService starting")

        let runtimeConfigProvider = RuntimeConfigProvider()
        let secretStore = InMemorySecretStore()
        let config = await runtimeConfigProvider.currentRuntimeConfig()

        let sttEngine = WhisperCPPBridgeSTTEngine(
            configuration: .init(
                modelPath: config.resolvedSTTModelPath(),
                language: config.sttLanguage
            )
        )

        let refinementEngine = RuntimeConfigRefinementEngine(
            runtimeConfigProvider: runtimeConfigProvider,
            secretStore: secretStore,
            canUseOpenAI: { false }
        )

        let coreClient = PipelineOrchestrator(
            sttEngine: sttEngine,
            refinementEngine: refinementEngine
        )

        let server = DictationHTTPServer(
            host: config.dictatorServerHost,
            port: config.dictatorServerPort,
            coreClient: coreClient
        )

        do
        {
            try await server.start()
            TraceLogger.log("listening on \(server.bindDescription)")
        }
        catch
        {
            TraceLogger.log("server failed: \(error)")
            exit(1)
        }

        let signalSource = DispatchSource.makeSignalSource(signal: SIGINT, queue: .main)
        await withCheckedContinuation
        { (continuation: CheckedContinuation<Void, Never>) in
            signalSource.setEventHandler
            {
                Task
                {
                    TraceLogger.log("shutting down")
                    await server.stop()
                    continuation.resume()
                }
            }
            signal(SIGINT, SIG_IGN)
            signalSource.resume()
        }
    }
}

import Foundation

enum TraceLogger {
    private static let defaultLogURL = URL(fileURLWithPath: "/tmp/dictator-trace.log")
    private static let formatter: ISO8601DateFormatter = {
        let formatter = ISO8601DateFormatter()
        formatter.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
        return formatter
    }()
    private static let lock = NSLock()
    private static var configuredLogURL: URL = defaultLogURL

    static func configure(logDirectoryPath: String?) {
        lock.lock()
        defer { lock.unlock() }

        guard let logDirectoryPath = logDirectoryPath?.trimmingCharacters(in: .whitespacesAndNewlines),
              !logDirectoryPath.isEmpty else {
            configuredLogURL = defaultLogURL
            ensureLogFileExists(at: configuredLogURL)
            return
        }

        let directoryURL = URL(fileURLWithPath: logDirectoryPath, isDirectory: true)
        configuredLogURL = directoryURL.appendingPathComponent("trace.log", isDirectory: false)
        ensureLogFileExists(at: configuredLogURL)
    }

    static func reset() {
        lock.lock()
        let current = configuredLogURL
        lock.unlock()
        ensureLogFileExists(at: current)
    }

    static func log(_ message: String) {
        lock.lock()
        let logURL = configuredLogURL
        lock.unlock()

        let timestamp = formatter.string(from: Date())
        let line = "[\(timestamp)] \(message)\n"

        if let data = line.data(using: .utf8) {
            ensureLogFileExists(at: logURL)
            if let handle = try? FileHandle(forWritingTo: logURL) {
                _ = try? handle.seekToEnd()
                try? handle.write(contentsOf: data)
                try? handle.close()
            }
        }

        fputs(line, stderr)
    }

    static var path: String {
        lock.lock()
        let path = configuredLogURL.path
        lock.unlock()
        return path
    }

    private static func ensureLogFileExists(at url: URL) {
        let directoryURL = url.deletingLastPathComponent()
        try? FileManager.default.createDirectory(at: directoryURL, withIntermediateDirectories: true)
        if !FileManager.default.fileExists(atPath: url.path) {
            FileManager.default.createFile(atPath: url.path, contents: nil)
        }
    }
}

